function ratingStars(value){const n=Math.max(0,Math.min(5,Math.round(Number(value)||0)));return '★'.repeat(n)+'☆'.repeat(5-n)}
async function loadProductRatings(refreshGrid=true){if(!supabaseClient)return;const {data,error}=await supabaseClient.from('product_reviews').select('product_id,rating');if(error){console.warn('Could not load product ratings:',error.message);return}productRatings.clear();for(const row of data||[]){const item=productRatings.get(row.product_id)||{sum:0,count:0};item.sum+=Number(row.rating)||0;item.count++;productRatings.set(row.product_id,item)}for(const item of productRatings.values())item.average=item.sum/item.count;if(refreshGrid)renderProducts($('#searchInput').value)}
async function loadProductReviews(product){const panel=$('#productReviews'),t=words[language];if(!panel)return;if(!product.dbId||!supabaseClient){panel.innerHTML=`<h3>${t.reviews}</h3><p>${t.noRatings}</p>`;return}const {data:reviews,error}=await supabaseClient.from('product_reviews').select('id,rating,review_text,created_at').eq('product_id',product.dbId).order('created_at',{ascending:false}).limit(30);if(panel.dataset.productId!==product.dbId)return;if(error){panel.innerHTML=`<h3>${t.reviews}</h3><p>${escapeHtml(error.message)}</p>`;return}const ratings=reviews||[],average=ratings.length?ratings.reduce((sum,r)=>sum+Number(r.rating),0)/ratings.length:0,summary=document.createElement('div');summary.className='product-review-summary';summary.innerHTML=ratings.length?`<span class="rating-stars">${ratingStars(average)}</span><b>${average.toFixed(1)}</b><small>${ratings.length} ${t.ratings}</small>`:`<small>${t.noRatings}</small>`;const list=document.createElement('div');list.className='product-review-list';list.innerHTML=ratings.map(review=>`<article><span class="rating-stars">${ratingStars(review.rating)}</span><small>${t.verifiedBuyer}</small>${review.review_text?`<p>${escapeHtml(review.review_text)}</p>`:''}</article>`).join('');panel.replaceChildren(Object.assign(document.createElement('h3'),{textContent:t.reviews}),summary,list);const {data:{session}}=await supabaseClient.auth.getSession();if(panel.dataset.productId!==product.dbId)return;if(!session){const signIn=document.createElement('button');signIn.type='button';signIn.className='auth-link-button';signIn.textContent=t.reviewSignin;signIn.onclick=()=>{setOverlay('productOverlay',false);setOverlay('accountOverlay',true);renderAccount()};panel.append(signIn);return}const ownResult=await supabaseClient.from('product_reviews').select('id,order_id,rating,review_text').eq('product_id',product.dbId).eq('user_id',session.user.id).maybeSingle();if(panel.dataset.productId!==product.dbId)return;if(ownResult.error){panel.insertAdjacentHTML('beforeend',`<p class="review-message">${escapeHtml(ownResult.error.message)}</p>`);return}let ownReview=ownResult.data,orderId=ownReview?.order_id;if(!ownReview){const eligibility=await supabaseClient.from('orders').select('id,order_items!inner(product_id)').eq('user_id',session.user.id).eq('status','delivered').eq('order_items.product_id',product.dbId).limit(1).maybeSingle();if(panel.dataset.productId!==product.dbId)return;if(eligibility.error){panel.insertAdjacentHTML('beforeend',`<p class="review-message">${escapeHtml(eligibility.error.message)}</p>`);return}orderId=eligibility.data?.id;if(!orderId){panel.insertAdjacentHTML('beforeend',`<p class="review-message">${t.reviewEligibility}</p>`);return}}const form=document.createElement('form');form.className='product-review-form';form.innerHTML=`<label>${t.yourRating}<select name="rating" required><option value="">—</option>${[5,4,3,2,1].map(value=>`<option value="${value}" ${Number(ownReview?.rating)===value?'selected':''}>${value} ★</option>`).join('')}</select></label><label>${t.reviewOptional}<textarea name="review_text" maxlength="500" placeholder="${t.reviewPlaceholder}">${escapeHtml(ownReview?.review_text||'')}</textarea></label><button class="button primary" type="submit">${ownReview?t.updateRating:t.submitRating}</button><p class="review-message" role="status"></p>`;form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button'),message=form.querySelector('.review-message');button.disabled=true;const payload={product_id:product.dbId,user_id:session.user.id,order_id:orderId,rating:Number(new FormData(form).get('rating')),review_text:String(new FormData(form).get('review_text')||'').trim()};const {error:saveError}=await supabaseClient.from('product_reviews').upsert(payload,{onConflict:'product_id,user_id'});button.disabled=false;if(saveError){message.textContent=`${t.ratingError} ${saveError.message}`;return}toast(t.ratingSaved);await loadProductRatings();await loadProductReviews(product)};panel.append(form)}
function quantityLimit(p){const stock=Number(p?.stockQuantity);return Math.max(0,Math.min(MAX_ORDER_QUANTITY,Number.isFinite(stock)?stock:MAX_ORDER_QUANTITY));}
function normalizeCartQuantities(checkStock=false){let adjusted=false;for(const [id,value] of Object.entries(cart)){const p=products.find(item=>item.id===id),max=p&&checkStock?quantityLimit(p):MAX_ORDER_QUANTITY,quantity=Math.max(0,Math.floor(Number(value)||0)),next=Math.min(max,quantity);if(next!==quantity)adjusted=true;if(next)cart[id]=next;else delete cart[id];}if(adjusted)localStorage.setItem('frostly-cart',JSON.stringify(cart));return adjusted;}
function saveCart(){localStorage.setItem('frostly-cart',JSON.stringify(cart));renderCart();}
function addItem(id){const p=products.find(item=>item.id===id),max=quantityLimit(p),next=(cart[id]||0)+1;if(next>max){toast(max>=MAX_ORDER_QUANTITY?words[language].maxCartQuantity:words[language].stockLimit);return;}cart[id]=next;saveCart();renderProducts($('#searchInput').value);toast(words[language].cartAdded);}
function renderCart(){const t=words[language];let count=Object.values(cart).reduce((a,b)=>a+b,0);$('#cartCount').textContent=count;const rows=Object.entries(cart).filter(([id,q])=>q>0&&products.some(p=>p.id===id));$('#cartItems').innerHTML=rows.length?rows.map(([id,q])=>{let p=products.find(x=>x.id===id),max=quantityLimit(p);return `<div class="cart-line"><img src="${escapeHtml(productImage(p))}" alt=""/><div><b>${escapeHtml(language==='en'?p.en:p.name)}</b><small>৳ ${Number(p.price)} · ${escapeHtml(language==='en'?p.weightEn:p.weight)}</small><div class="qty"><button data-qty="${escapeHtml(id)}" data-delta="-1" aria-label="${language==='en'?'Decrease quantity':'পরিমাণ কমান'}">−</button><span>${Number(q)}</span><button data-qty="${escapeHtml(id)}" data-delta="1" aria-label="${language==='en'?'Increase quantity':'পরিমাণ বাড়ান'}" ${q>=max?'disabled title="'+escapeHtml(max>=MAX_ORDER_QUANTITY?t.maxCartQuantity:t.stockLimit)+'"':''}>＋</button></div></div><span class="line-price">৳ ${Number(p.price)*Number(q)}</span></div>`}).join(''):`<div class="empty-cart">${t.emptyCart}</div>`;let total=rows.reduce((a,[id,q])=>a+products.find(p=>p.id===id).price*q,0);$('#cartSubtotal').textContent=`৳ ${total.toLocaleString('en-BD')}`;document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{const id=b.dataset.qty,p=products.find(item=>item.id===id),next=(cart[id]||0)+Number(b.dataset.delta),max=quantityLimit(p);if(next>max){toast(max>=MAX_ORDER_QUANTITY?t.maxCartQuantity:t.stockLimit);return;}cart[id]=Math.max(0,next);if(!cart[id])delete cart[id];saveCart();});}
