  const content=$('#ordersDrawerContent');content.innerHTML=`<div class="orders-drawer-message">${t.loadingOrders}</div>`;
  if(!supabaseClient){content.innerHTML=`<p class="setup-message">${t.setup}<br/>${t.setupSteps}</p>`;return;}
