  if(sessionError){content.innerHTML=`<p class="setup-message">${escapeHtml(supabaseMessage(sessionError))}</p>`;return;}
  if(!session){content.innerHTML=`<div class="orders-signin"><span class="orders-signin-icon">▤</span><h3>${t.signInForOrders}</h3><p>${t.signInForOrdersCopy}</p><button id="ordersSignInButton" class="button primary full">${t.signin}</button></div>`;$('#ordersSignInButton').onclick=()=>{setOverlay('ordersOverlay',false);setOverlay('accountOverlay',true);renderAccount();};return;}
