  content.querySelectorAll('[data-drawer-order-filter]').forEach(button=>button.onclick=()=>{content.querySelectorAll('[data-drawer-order-filter]').forEach(item=>item.classList.toggle('active',item===button));$('#ordersDrawerList').innerHTML=renderCustomerOrderCards(orders,button.dataset.drawerOrderFilter);});
